    out = [row[:] for row in grid]
    colors = {v for row in grid for v in row if v != 1}

    for color in colors:
        points = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == color]
        lines = set()
        for i, (r, c) in enumerate(points):
            for rr, cc in points[i + 1:]:
                dr, dc = rr - r, cc - c
                if dr and abs(dr) == abs(dc):
                    if dr < 0:
                        dr, dc = -dr, -dc
                    lines.add((dr, dc, c - dc * r))

        for dr, dc, invariant in lines:
            # Extend from the colored cells in both directions, stopping at
            # other existing objects rather than overwriting them.
            on_line = [(r, c) for r, c in points
                       if c == invariant + dc * r]
            if not on_line:
                continue
            for r, c in on_line:
                for sign in (-1, 1):
                    rr, cc = r + sign * dr, c + sign * dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if out[rr][cc] != 1:
                            break
                        out[rr][cc] = color
                        rr += sign * dr
                        cc += sign * dc
    return out
